 "content": "def transform(grid):
    """Connect diagonal 1 markers and extend crossing 6 markers perpendicularly."""
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    ones = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 1]
    sixes = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 6]

    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr_raw, dc_raw = r2 - r1, c2 - c1
            if dr_raw == 0 or abs(dr_raw) != abs(dc_raw):
                continue
            dr = 1 if dr_raw > 0 else -1
            dc = 1 if dc_raw > 0 else -1

            # Complete the diagonal segment between these 1 markers.
            r, c = r1, c1
            while True:
                if grid[r][c] != 6:
                    out[r][c] = 1
                if (r, c) == (r2, c2):
                    break
                r += dr
                c += dc

            # A 6 on this segment marks the perpendicular diagonal, extending
            # in both directions to the grid edges.
            for sr, sc in sixes:
                if (sr - r1) * dc_raw != (sc - c1) * dr_raw:
                    continue
                if not (min(r1, r2) <= sr <= max(r1, r2)):
                    continue
                if not (min(c1, c2) <= sc <= max(c1, c2)):
                    continue
                r, c = sr, sc
                while 0 <= r < height and 0 <= c < width:
                    if grid[r][c] != 1:
                        out[r][c] = 6
                    r -= dr
                    c += dc
                r, c = sr + dr, sc - dc
                while 0 <= r < height and 0 <= c < width:
                    if grid[r][c] != 1:
                        out[r][c] = 6
                    r += dr
                    c -= dc

    return out
